import 'package:flutter/material.dart'; import '../models/user.dart'; import '../services/api.dart'; import '../widgets.dart'; import 'chat.dart';
class People extends StatefulWidget{final User user;const People({super.key,required this.user});@override State<People> createState()=>_PeopleState();}
class _PeopleState extends State<People>{final q=TextEditingController();List data=[];@override void dispose(){q.dispose();super.dispose();}Future<void> search(String v)async{if(v.trim().isEmpty){setState(()=>data=[]);return;}try{final r=await Api.get('/users/search?q=${Uri.encodeQueryComponent(v.trim())}');if(mounted)setState(()=>data=List.from(r['users']??[]));}catch(_){} }@override Widget build(BuildContext c)=>Column(children:[GradientHeader(title:'Meet the campus',subtitle:'Find classmates, friends and creators'),Padding(padding:const EdgeInsets.all(16),child:TextField(controller:q,onChanged:search,decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search by name or email',filled:true))),Expanded(child:data.isEmpty?const EmptyState(icon:Icons.person_search,title:'Search for someone',text:'Type a name or email to start a conversation.'):ListView.builder(padding:const EdgeInsets.symmetric(horizontal:16),itemCount:data.length,itemBuilder:(c,i){final u=Map<String,dynamic>.from(data[i]);final id='${u['_id']??u['id']??''}',name='${u['name']??'Student'}';return Padding(padding:const EdgeInsets.only(bottom:8),child:Card(child:ListTile(contentPadding:const EdgeInsets.all(12),leading:Avatar(name:name,url:'${u['profilePic']??''}'),title:Text(name,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${u['bio']??u['email']??''}'),trailing:const Icon(Icons.chat_bubble_outline),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Chat(user:widget.user,directUserId:id,title:name)))));}))]);}
